#!/usr/bin/env python3
"""Add the Greek/Latin notation teaching layer to the 2026 weekly pages."""
from pathlib import Path
ROOT=Path(__file__).parent/'site'/'2026'
CSS=r'''
.bayer-toggle-wrap{max-width:1080px;margin:0 auto;padding:.75rem 1.5rem 0;font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}.bayer-toggle{display:flex;align-items:center;justify-content:flex-end;gap:.35rem;font-size:.86rem}.bayer-toggle-label{margin-right:.2rem;color:var(--muted)}.bayer-toggle button{appearance:none;border:1px solid #c8d3dc;background:#fff;color:var(--link);padding:.35rem .62rem;border-radius:.4rem;font:inherit;cursor:pointer}.bayer-toggle button[aria-pressed=true]{background:var(--navy);color:#fff;border-color:var(--navy)}.notation-legend{max-width:1080px;margin:.55rem auto 0;padding:.55rem 1.5rem;font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;font-size:.78rem;line-height:1.55;color:var(--muted)}.notation-legend p{max-width:none;margin:.2rem 0}.notation-legend strong{color:inherit}.notation-legend[hidden]{display:none}
@media(max-width:760px) and (orientation:portrait){.bayer-toggle-wrap,.notation-legend{padding-left:1rem;padding-right:1rem}table.calendar th:first-child,table.calendar td:first-child{width:22%}table.calendar th:nth-child(2),table.calendar td:nth-child(2){width:18%}table.calendar th:nth-child(3),table.calendar td:nth-child(3){width:60%}table.calendar td:nth-child(2){white-space:normal;text-align:center}.zodiac-day{display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1.2}.zodiac-day .zodiac-day-number{display:block;margin-top:.18rem}}
@media(prefers-color-scheme:dark){.bayer-toggle button{background:#1c2a36;border-color:#405567;color:#b6dcff}.bayer-toggle button[aria-pressed=true]{background:#eef7ff;color:#102a43;border-color:#eef7ff}}
'''.strip()
HTML=r'''<div class="bayer-toggle-wrap"><div class="bayer-toggle" role="group" aria-label="Astronomical notation"><span class="bayer-toggle-label">Notation:</span><button type="button" data-bayer-mode="greek" aria-pressed="true">Greek</button><button type="button" data-bayer-mode="latin" aria-pressed="false">Latin</button></div></div><aside class="notation-legend" aria-label="Greek notation legend"><p><strong>Greek alphabet:</strong> α Alpha · β Beta · γ Gamma · δ Delta · ε Epsilon · ζ Zeta · η Eta · θ Theta · ι Iota · κ Kappa · λ Lambda · μ Mu · ν Nu · ξ Xi · ο Omicron · π Pi · ρ Rho · σ Sigma · τ Tau · υ Upsilon · φ Phi · χ Chi · ψ Psi · ω Omega</p><p><strong>Zodiac:</strong> ♈ Aries · ♉ Taurus · ♊ Gemini · ♋ Cancer · ♌ Leo · ♍ Virgo · ♎ Libra · ♏ Scorpio · ♐ Sagittarius · ♑ Capricorn · ♒ Aquarius · ♓ Pisces</p><p><strong>Ephemerides:</strong> ☉ Sun · ☽ Moon · ☿ Mercury · ♀ Venus · ♂ Mars · ♃ Jupiter · ♄ Saturn</p></aside>'''
JS=r'''<script>(function(){const g={'α':'Alpha','β':'Beta','γ':'Gamma','δ':'Delta','ε':'Epsilon','ζ':'Zeta','η':'Eta','θ':'Theta','ι':'Iota','κ':'Kappa','λ':'Lambda','μ':'Mu','ν':'Nu','ξ':'Xi','ο':'Omicron','π':'Pi','ρ':'Rho','σ':'Sigma','τ':'Tau','υ':'Upsilon','φ':'Phi','χ':'Chi','ψ':'Psi','ω':'Omega'},c={Cen:'Centauri',Aqr:'Aquarii',Ari:'Arietis',Tau:'Tauri',Gem:'Geminorum',Cnc:'Cancri',Leo:'Leonis',Vir:'Virginis',Lib:'Librae',Sco:'Scorpii',Sgr:'Sagittarii',Cap:'Capricorni',Psc:'Piscium',Ori:'Orionis',Peg:'Pegasi',And:'Andromedae',Cyg:'Cygni',Lyr:'Lyrae',Aql:'Aquilae',UMa:'Ursae Majoris',UMi:'Ursae Minoris',Cas:'Cassiopeiae',Per:'Persei',Oph:'Ophiuchi',Boo:'Bootis',CrB:'Coronae Borealis',Her:'Herculis'},z={'♈':'Aries','♉':'Taurus','♊':'Gemini','♋':'Cancer','♌':'Leo','♍':'Virgo','♎':'Libra','♏':'Scorpio','♐':'Sagittarius','♑':'Capricorn','♒':'Aquarius','♓':'Pisces'},b={'☉':'Sun','☽':'Moon','☿':'Mercury','♀':'Venus','♂':'Mars','♃':'Jupiter','♄':'Saturn'};function span(x,y){let s=document.createElement('span');s.className='notation-item';s.dataset.greek=x;s.dataset.latin=y;s.textContent=x;return s}document.querySelectorAll('.zodiac-glyph').forEach(s=>{let x=s.textContent.charAt(0);if(z[x]){s.classList.add('notation-item');s.dataset.greek=x;s.dataset.latin=z[x]}});let main=document.querySelector('main'),re=/([αβγδεζηθικλμνξοπρστυφχψω])(\d+)?\s+([A-Z][A-Za-z]{2})\b|[☉☽☿♀♂♃♄]|([αβγδεζηθικλμνξοπρστυφχψω])(\d+)?/g,n=[];let w=document.createTreeWalker(main,NodeFilter.SHOW_TEXT);while(w.nextNode()){if(!w.currentNode.parentElement.closest('.notation-item')&&re.test(w.currentNode.nodeValue))n.push(w.currentNode);re.lastIndex=0}n.forEach(node=>{let t=node.nodeValue,f=document.createDocumentFragment(),last=0,m;re.lastIndex=0;while((m=re.exec(t))){f.append(document.createTextNode(t.slice(last,m.index)));let x=m[0],y=x,bm=x.match(/^([αβγδεζηθικλμνξοπρστυφχψω])(\d+)?\s+([A-Z][A-Za-z]{2})$/),gm=x.match(/^([αβγδεζηθικλμνξοπρστυφχψω])(\d+)?$/);if(bm)y=g[bm[1]]+(bm[2]||'')+' '+(c[bm[3]]||bm[3]);else if(b[x])y=b[x];else if(gm)y=g[gm[1]]+(gm[2]||'');f.append(span(x,y));last=m.index+x.length}f.append(document.createTextNode(t.slice(last)));node.replaceWith(f)});document.querySelectorAll('table.calendar tbody td:nth-child(2)').forEach(td=>{let txt=td.textContent.trim(),m=txt.match(/^([^\d]*?)(\d+)$/);if(!m)return;let number=m[2],nodes=Array.from(td.childNodes);td.classList.add('zodiac-day');nodes.forEach(node=>{if(node.nodeType===3)node.nodeValue=node.nodeValue.replace(/\s*\d+\s*$/,'')});let d=document.createElement('span');d.className='zodiac-day-number';d.textContent=number;td.append(d)});let buttons=document.querySelectorAll('[data-bayer-mode]'),legend=document.querySelector('.notation-legend');function setMode(mode){document.querySelectorAll('.notation-item').forEach(s=>s.textContent=mode==='latin'?s.dataset.latin:s.dataset.greek);buttons.forEach(x=>x.setAttribute('aria-pressed',x.dataset.bayerMode===mode?'true':'false'));if(legend)legend.hidden=mode==='latin';try{localStorage.setItem('star-almanack-bayer-mode',mode)}catch(_){}}buttons.forEach(x=>x.addEventListener('click',()=>setMode(x.dataset.bayerMode)));let initial='greek';try{let s=localStorage.getItem('star-almanack-bayer-mode');if(s==='latin'||s==='greek')initial=s}catch(_){}setMode(initial)})();</script>'''
def add(path):
 t=path.read_text(encoding='utf-8')
 if 'data-bayer-mode="greek"' in t:return
 t=t.replace('</style>',CSS+'\n</style>',1).replace('</header>','</header>'+HTML,1).replace('</body>',JS+'</body>',1)
 path.write_text(t,encoding='utf-8')
def main():
 pages=sorted(ROOT.glob('W??/index.html'))
 if len(pages)!=53:raise SystemExit(f'Expected 53 weekly pages, found {len(pages)}')
 for p in pages:add(p)
 print('Added notation toggle, Greek legend, and portrait zodiac layout to 53 weekly pages')
if __name__=='__main__':main()
